package com.gameaggregator.authorizationservice.domain; import com.gameaggregator.platform.core.common.persistence.BaseEntity; import jakarta.persistence.*; import java.util.UUID; @Entity @Table(name="authorization_audits") public class AuthorizationAudit extends BaseEntity{@Column(nullable=false)private UUID userId;@Column(nullable=false)private UUID tenantId;@Column(nullable=false,length=150)private String permission;@Column(nullable=false)private boolean allowed;@Column(nullable=false,length=500)private String reason;protected AuthorizationAudit(){}public AuthorizationAudit(UUID userId,UUID tenantId,String permission,boolean allowed,String reason){this.userId=userId;this.tenantId=tenantId;this.permission=permission;this.allowed=allowed;this.reason=reason;}}
